//! The SQLite repository of events against a real database
//! migrated with the application's migrations: round trip, optimistic
//! locking and cursor pages, plus tenant isolation. Generated by
//! `forge generate scaffold`.
//!
//! SQLite tests use a temporary file and always run.

use std::error::Error;

use app::application::ports::event_repository::{EventRepository, EventStoreError};
use app::application::use_cases::events::WRITE_PERMISSION;
use app::domain::entities::event::{Event, EventAttributes};
use app::infrastructure::database::events::SqliteEventRepository;
use forge::auth::{Session, UnixTimestamp};
use forge::core::{Timestamp, Uuid, Version};
use forge::db::SqliteDatabase;
use forge::db::testing::TestDatabase;
use forge::security::{Permission, PrincipalId, RbacPolicy, Role};
use forge::tenancy::{Membership, TenantContext, TenantId};

type TestResult = Result<(), Box<dyn Error>>;

static MIGRATOR: sqlx::migrate::Migrator = sqlx::migrate!();

fn attributes() -> Result<EventAttributes, Box<dyn Error>> {
    Ok(EventAttributes {
        name: "Example name".to_owned(),
        notes: Some("Example notes".to_owned()),
        starts_at: Timestamp::parse("2026-01-02T03:04:05.123456Z")?,
        ends_at: Some(Timestamp::parse("2026-01-02T03:04:05.123456Z")?),
        capacity: 42,
        attendees: Some(42),
        public: true,
        featured: Some(true),
        venue: Uuid::from_u128(0x67e5_5044_10b1_426f_9247_bb68_0e5f_e0c8),
        organizer: Some(Uuid::from_u128(0x67e5_5044_10b1_426f_9247_bb68_0e5f_e0c8)),
    })
}

/// An authorized context of `tenant`, built like the HTTP adapter builds it.
fn context(tenant: TenantId) -> Result<TenantContext, Box<dyn Error>> {
    let principal = PrincipalId::new();
    let authenticated = Session::new(
        principal,
        UnixTimestamp::from_secs(10),
        UnixTimestamp::from_secs(20),
    )?
    .authenticate(UnixTimestamp::from_secs(11))?;
    let role = Role::new("member")?;
    let permission = Permission::new(WRITE_PERMISSION)?;
    let mut policy = RbacPolicy::new();
    policy.allow(role.clone(), permission.clone());
    let membership = Membership::active(tenant, principal, vec![role]);
    Ok(TenantContext::authorize(
        authenticated,
        &membership,
        &policy,
        &permission,
    )?)
}

async fn exercise(database: &SqliteDatabase) -> TestResult {
    let repository = SqliteEventRepository::new(database.clone());
    let tenant = context(TenantId::new())?;
    let other = context(TenantId::new())?;
    let event = Event::new(attributes()?)?;

    repository.insert(&tenant, &event).await?;
    assert_eq!(
        repository.find(&tenant, event.id()).await?,
        Some(event.clone())
    );

    let version = repository.update(&tenant, &event).await?;
    assert_eq!(version.get(), 2);
    assert!(matches!(
        repository.update(&tenant, &event).await,
        Err(EventStoreError::Conflict)
    ));
    assert!(matches!(
        repository
            .delete(&tenant, event.id(), Version::INITIAL)
            .await,
        Err(EventStoreError::Conflict)
    ));
    let stored = repository.find(&tenant, event.id()).await?;
    assert_eq!(stored.map(|stored| stored.version()), Some(version));

    for _ in 0..2 {
        repository
            .insert(&tenant, &Event::new(attributes()?)?)
            .await?;
    }
    let first = repository.page(&tenant, None, 2).await?;
    assert_eq!(first.events.len(), 2);
    assert_eq!(first.events[0].id(), event.id());
    assert!(first.next.is_some());
    let rest = repository.page(&tenant, first.next, 2).await?;
    assert_eq!(rest.events.len(), 1);
    assert!(rest.next.is_none());

    // Another tenant sees nothing and cannot change or delete the row.
    assert_eq!(repository.find(&other, event.id()).await?, None);
    assert!(repository.page(&other, None, 10).await?.events.is_empty());
    let current = event.clone().with_version(version);
    assert!(matches!(
        repository.update(&other, &current).await,
        Err(EventStoreError::Conflict)
    ));
    assert!(matches!(
        repository.delete(&other, event.id(), version).await,
        Err(EventStoreError::Conflict)
    ));
    assert!(repository.find(&tenant, event.id()).await?.is_some());

    repository.delete(&tenant, event.id(), version).await?;
    assert_eq!(repository.find(&tenant, event.id()).await?, None);
    Ok(())
}

#[tokio::test]
async fn sqlite_round_trip_locking_and_pages() -> TestResult {
    let database = TestDatabase::<sqlx::Sqlite>::create(&MIGRATOR).await?;
    exercise(database.database()).await?;
    database.cleanup().await?;
    Ok(())
}
